template <typename T>
__aicore__ inline void RowMuls(LocalTensor<T> dstUb, LocalTensor<T> src0Ub,
                               LocalTensor<T> src1Ub, uint32_t dealRowCount,
                               uint32_t columnCount, uint32_t actualColumnCount) {
    AscendC::BinaryRepeatParams repeatParams;
    repeatParams.src1BlkStride = 0;  // Broadcast mode
    repeatParams.src1RepStride = 1; // Advance 1 block per row
    AscendC::Mul(dstUb, src0Ub, src1Ub, columnCount, dealRowCount, repeatParams);
}
